def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid separator row or column.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            half = (h - 1) // 2
            top = grid[:r]
            bottom = grid[r + 1:]
            return [
                [2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                 for j in range(w)]
                for i in range(min(len(top), len(bottom), half))
            ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            width = min(c, w - c - 1)
            return [
                [2 if left[r][j] != 0 and right[r][j] != 0 else 0
                 for j in range(width)]
                for r in range(h)
            ]

    return [[0 for _ in row] for row in grid]
